function newFranjaId() {
  return typeof crypto !== 'undefined' && crypto.randomUUID
    ? crypto.randomUUID()
    : `fj-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

function normalizeFranjasHorarias(raw) {
  if (!Array.isArray(raw)) return [];
  return raw.map((f) => ({
    id: String(f?.id || '').trim() || newFranjaId(),
    tipo: String(f?.tipo || '').trim() === 'fecha_especial' ? 'fecha_especial' : 'semanal',
    nombre: String(f?.nombre ?? '').trim(),
    fecha: String(f?.fecha ?? '').trim().slice(0, 10),
    dias: Array.isArray(f?.dias)
      ? f.dias.map((d) => String(d).trim()).filter((d) => DIAS_SEMANA_DEFAULT_FRANJA.includes(d))
      : DIAS_SEMANA_DEFAULT_FRANJA,
    hora_inicio: String(f?.hora_inicio ?? '').trim().slice(0, 5),
    hora_fin: String(f?.hora_fin ?? '').trim().slice(0, 5),
    precio:
      f?.precio === '' || f?.precio == null
        ? ''
        : String(f.precio).replace(/\./g, '').replace(/[^\d]/g, ''),
  }));
}

/** Estado de formulario «Mi Sede» desde fila Supabase / API. */
function sedeDbRowToMiSedeFormState(sedeData) {
  if (!sedeData) return {};
  return {
    nombre: sedeData.nombre || '',
    direccion: sedeData.direccion || '',
    ciudad: sedeData.ciudad || '',
    provincia: sedeData.provincia != null ? String(sedeData.provincia) : '',
    pais: sedeData.pais || '',
    telefono: sedeData.telefono || '',
    email_contacto: sedeData.email_contacto || '',
    horario_apertura: sedeData.horario_apertura || '',
    horario_cierre: sedeData.horario_cierre || '',
    precio_60min: sedeData.precio_60min ?? '',
    precio_90min: sedeData.precio_90min ?? sedeData.precio_turno ?? '',
    precio_120min: sedeData.precio_120min ?? '',
    precio_turno: sedeData.precio_turno ?? sedeData.precio_90min ?? '',
    moneda: sedeData.moneda || 'ARS',
    surge_activo: parseSurgeActivo(sedeData.surge_activo),
    descripcion: sedeData.descripcion || '',
    slogan: sedeData.slogan != null ? String(sedeData.slogan) : '',
    historia: sedeData.historia != null ? String(sedeData.historia) : '',
    anio_fundacion:
      sedeData.anio_fundacion != null && String(sedeData.anio_fundacion).trim() !== ''
        ? String(sedeData.anio_fundacion).trim()
        : '',
    metodo_pago: sedeData.metodo_pago || 'mercadopago',
    // Credenciales write-only: nunca se copian desde Backend / GET / PATCH.
    stripe_account_id: '',
    mp_access_token: '',
    mp_public_key: '',
    pago_manual_instrucciones: sedeData.pago_manual_instrucciones || '',
    latitud: sedeData.latitud != null ? String(sedeData.latitud) : '',
    longitud: sedeData.longitud != null ? String(sedeData.longitud) : '',
    instagram: sedeData.instagram || '',
    facebook: sedeData.facebook || '',
    tiktok: sedeData.tiktok || '',
    twitter: sedeData.twitter || '',
    youtube: sedeData.youtube || '',
    website: sedeData.website || '',
    amenities: normalizeSedeAmenities(sedeData.amenities),
  };
}

/** Merge DB sede into form with país option + WhatsApp prefix (MEJ-01). */
function mergeMiSedeFormFromDb(updated, prevForm = {}, paisOptions = []) {
  const base = { ...prevForm, ...sedeDbRowToMiSedeFormState(updated) };
  const pais = paisOptionValueFromStored(base.pais, paisOptions) || base.pais;
  const ensured = ensureWhatsappPrefixed(base.telefono, pais);
  // Forzar write-only: aunque updated trajera secretos, no quedan en el form.
  return clearPagosCredentialFields({ ...base, pais, telefono: ensured.phone });
}


function precioDuracionInputDisplay(raw) {
  if (raw === '' || raw == null) return '';
  const n = parsePrecioDuracionField(raw);
  return n != null ? Number(n).toLocaleString('es-AR') : '';
}

function parseSurgePctField(raw, { min = 0, max = 100, fallback = 0 } = {}) {
  if (raw === '' || raw == null) return fallback;
  const n = parseInt(String(raw).replace(/\D/g, ''), 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function parseSurgeActivo(raw) {
  return raw === true || raw === 'true' || raw === 1 || raw === '1';
}

function surgeConfigFromApiRow(row) {
  const dep = String(row?.deporte || '').trim().toLowerCase();
  if (!dep) return null;
  return {
    deporte: dep,
    config: defaultSurgeConfig({
      activo: parseSurgeActivo(row.activo),
      descuento_max_pct:
        row.descuento_max_pct != null ? String(row.descuento_max_pct) : '20',
      aumento_max_pct:
        row.aumento_max_pct != null ? String(row.aumento_max_pct) : '40',
    }),
  };
}

function buildSurgeConfigsFromApi(configs) {
  const map = {};
  for (const { key } of DEPORTES_CANCHA_SEDE_OPTIONS) {
    map[key] = defaultSurgeConfig();
  }
  for (const row of Array.isArray(configs) ? configs : []) {
    const parsed = surgeConfigFromApiRow(row);
    if (parsed && map[parsed.deporte] != null) {
      map[parsed.deporte] = parsed.config;
    }
  }
  return map;
}

function extractSurgeDeportesFromCanchas(canchas) {
  const list = Array.isArray(canchas) ? canchas : [];
  const deportes = [...new Set(list.map((c) => c.deporte).filter(Boolean))];
  return deportes.map((raw) => String(raw).trim().toLowerCase()).filter(Boolean);
}

function surgeDeporteRowsFromCanchas(canchas) {
  const deportes = extractSurgeDeportesFromCanchas(canchas);
  const labelByKey = Object.fromEntries(DEPORTES_CANCHA_SEDE_OPTIONS.map((o) => [o.key, o.label]));
  const list = Array.isArray(canchas) ? canchas : [];
  return deportes.map((key) => {
    if (isDeporteCustom(key)) {
      const first = list.find((c) => isDeporteCustom(c?.deporte));
      return {
        key,
        label: resolveCanchaDeporteLabel(first || { deporte: 'custom' }, {
          customFallback: 'Otro / Personalizado',
        }),
      };
    }
    return {
      key,
      label: labelByKey[key] || key.charAt(0).toUpperCase() + key.slice(1),
    };
  });
}

function defaultSurgeConfig(overrides = {}) {
  return {
    activo: false,
    descuento_max_pct: '20',
    aumento_max_pct: '40',
    ...overrides,
  };
}

function surgeConfigBandError() {
  return null;
}

function formatSurgePricePreview(baseRaw, descuentoPctRaw, aumentoPctRaw) {
  const base = parsePrecioDuracionField(baseRaw);
  if (base == null) return null;
  const desc = parseSurgePctField(descuentoPctRaw, { min: 0, max: 50, fallback: 20 });
  const aum = parseSurgePctField(aumentoPctRaw, { min: 0, max: 100, fallback: 40 });
  const min = Math.round(base * (1 - desc / 100));
  const max = Math.round(base * (1 + aum / 100));
  const fmt = (n) => Number(n).toLocaleString('es-AR');
  return `90 min: $${fmt(base)} → entre $${fmt(min)} y $${fmt(max)}`;
}

/** Body para PATCH /api/sedes/:id (campos alineados con el panel). */
function miSedeFormToApiPatchBody(form) {
  const duracionPrecios = preciosDuracionToApiPatch(form);
  const latOk = form.latitud !== '' && form.latitud != null && Number.isFinite(parseFloat(form.latitud));
  const lngOk = form.longitud !== '' && form.longitud != null && Number.isFinite(parseFloat(form.longitud));
  const mpTrim = String(form.mp_access_token ?? '').trim();
  const mpPublicTrim = String(form.mp_public_key ?? '').trim();
  const stripeTrim = String(form.stripe_account_id ?? '').trim();
  const out = {
    nombre: form.nombre,
    direccion: form.direccion || null,
    ciudad: form.ciudad || null,
    provincia:
      form.provincia != null && String(form.provincia).trim() !== '' ? String(form.provincia).trim() : null,
    pais: form.pais || null,
    telefono: normalizeWhatsappForStorage(form.telefono, form.pais),
    email_contacto: form.email_contacto || null,
    horario_apertura: form.horario_apertura || null,
    horario_cierre: form.horario_cierre || null,
    ...duracionPrecios,
    moneda: form.moneda || 'ARS',
    descripcion: form.descripcion || null,
    slogan:
      form.slogan != null && String(form.slogan).trim() !== ''
        ? String(form.slogan).trim().slice(0, 80)
        : null,
    historia:
      form.historia != null && String(form.historia).trim() !== ''
        ? String(form.historia).trim().slice(0, 500)
        : null,
    anio_fundacion: (() => {
      const s = String(form.anio_fundacion ?? '').trim();
      if (!s) return null;
      const y = parseInt(s, 10);
      return Number.isFinite(y) && y >= 1800 && y <= 2100 ? y : null;
    })(),
    metodo_pago: form.metodo_pago || 'mercadopago',
    pago_manual_instrucciones: form.pago_manual_instrucciones || null,
    latitud: latOk ? parseFloat(form.latitud) : null,
    longitud: lngOk ? parseFloat(form.longitud) : null,
    instagram: form.instagram || null,
    facebook: form.facebook || null,
    tiktok: form.tiktok || null,
    twitter: form.twitter || null,
    youtube: form.youtube || null,
    website: form.website || null,
    amenities: normalizeSedeAmenities(form.amenities),
  };
  // Credenciales: solo si el admin escribió un valor nuevo (nunca vacíos).
  Object.assign(out, sanitizePagosPartialPayload({
    mp_access_token: mpTrim,
    mp_public_key: mpPublicTrim,
    stripe_account_id: stripeTrim,
  }));
  return out;
}

const EMPTY_PREMIO_FORM = () => ({
  nombre: '',
  descripcion: '',
  costo_padcoins: '',
  stock_total: '',
  stock_disponible: '',
  condiciones: '',
  fecha_inicio: '',
  fecha_fin: '',
  activo: true,
});

function validatePremioForm(form) {
  if (!(form.nombre || '').trim()) return 'El nombre es obligatorio';

  const costo = parseInt(form.costo_padcoins, 10);
  if (!Number.isFinite(costo) || costo <= 0) return 'El costo en PadCoins debe ser mayor a 0';

  const hasStockTotal = form.stock_total !== '' && form.stock_total != null;
  const hasStockDisp = form.stock_disponible !== '' && form.stock_disponible != null;
  const stockTotal = hasStockTotal ? parseInt(form.stock_total, 10) : null;
  const stockDisp = hasStockDisp ? parseInt(form.stock_disponible, 10) : null;

  if (stockTotal !== null && (!Number.isFinite(stockTotal) || stockTotal < 0)) {
    return 'El stock total no puede ser negativo';
  }
  if (stockDisp !== null && (!Number.isFinite(stockDisp) || stockDisp < 0)) {
    return 'El stock disponible no puede ser negativo';
  }
  if (stockTotal !== null && stockDisp !== null && stockDisp > stockTotal) {
    return 'El stock disponible no puede superar el stock total';
  }

  const fi = String(form.fecha_inicio || '').trim();
  const ff = String(form.fecha_fin || '').trim();
  if (fi && ff && fi > ff) return 'La fecha de inicio no puede ser posterior a la fecha de fin';

  return null;
}

function buildPremioPayload(form, sede_id) {
  const payload = {
    sede_id: parseInt(sede_id, 10),
    nombre: form.nombre.trim(),
    descripcion: (form.descripcion || '').trim() || null,
    costo_padcoins: parseInt(form.costo_padcoins, 10),
    condiciones: (form.condiciones || '').trim() || null,
    activo: !!form.activo,
  };
  if (form.stock_total !== '' && form.stock_total != null) {
    payload.stock_total = parseInt(form.stock_total, 10);
  }
  if (form.stock_disponible !== '' && form.stock_disponible != null) {
    payload.stock_disponible = parseInt(form.stock_disponible, 10);
  }
  const fi = String(form.fecha_inicio || '').trim();
  const ff = String(form.fecha_fin || '').trim();
  if (fi) payload.fecha_inicio = fi;
  if (ff) payload.fecha_fin = ff;
  return payload;
}

