const PC_ALERT_SEVERIDAD_FILTRO = [
  { id: '', label: 'Todas las severidades' },
  { id: 'alta', label: 'Alta (crítica / revisar)' },
  { id: 'media', label: 'Media (atención)' },
  { id: 'baja', label: 'Baja (informativa)' },
];

