  useEffect(() => {
    if (sedeIdKey && !sbSedeId) setSbSedeId(String(sedeIdKey));
  }, [sedeIdKey, sbSedeId]);

  useEffect(() => {
    if (sedeIdKey && !pcSedeId) setPcSedeId(String(sedeIdKey));
    else if (sedeId != null && sedeId !== '' && !pcSedeId) setPcSedeId(String(sedeId));
  }, [sedeIdKey, sedeId, pcSedeId]);

  useEffect(() => {
    if (activeTab !== 'padcoins') return;
    if (isSuperAdmin) {
      void fetchPadcoinsGlobalConfig();
      void fetchPadcoinsSedesParticipacionList();
      void fetchPadcoinsAlertas(0);
    }
    if (isSuperAdmin || esAdminClub) {
      void fetchPadcoinsCampaigns();
    } else {
      setPcCampaigns([]);
      setPcCampaignsError('');
      setPcCampaignsLoading(false);
      cerrarCampanaForm();
      cerrarResumenCampana();
    }
    const sid = resolvePcSedeId();
    if (!sid) {
      setPremios([]);
      setPremiosError('');
      setPremiosLoading(false);
      setCanjes([]);
      setCanjesError('');
      setCanjesLoading(false);
      setPcSedeParticipacion(emptyPadcoinsSedeConfigForm());
      setPcSedeParticipacionError('');
      setPcSedeParticipacionLoading(false);
      setPcSedeSmartConfig(null);
      setPcSedeSmartForm(emptyPcSedeSmartOverrideForm());
      setPcSedeSmartError('');
      setPcSedeSmartLoading(false);
      if (esAdminClub) {
        setPcMovimientos([]);
        setPcMovError('');
        setPcMovTotal(0);
        setPcMovLoading(false);
        return;
      }
      void fetchPadcoinsMovimientos(0);
      return;
    }
    void fetchPadcoinsSedeParticipacion(sid);
    void fetchPadcoinsSedeSmartConfig(sid);
    fetchPremios();
    fetchCanjes();
    if (esAdminClub && sid) setPcMovFiltroSedeId(String(sid));
    void fetchPadcoinsMovimientos(0);
  }, [activeTab, pcSedeId, sedeId, sedeIdKey, apiBaseUrl, esAdminClub, isSuperAdmin, esAdminNacional, pcCampaignFiltroSedeId]); // eslint-disable-line react-hooks/exhaustive-deps

