              borderRadius: '50%',
              minWidth: '18px',
              height: '18px',
              padding: '0 4px',
              fontSize: '11px',
              fontWeight: 'bold',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              border: '1px solid var(--border)',
