          <div className={`admin-super-header__logo-wrap${isSuperAdmin ? ' admin-super-header__logo-wrap--super' : ''}`}>
            <img className={`admin-super-header__logo${isSuperAdmin ? ' admin-super-header__logo--super' : ''}`} src={logoPanelSrc} alt="" />
          </div>
