                    const dr = miSedeDuracionDrafts[row.id] || { precio: '', activo: !!row.activo };
                    const mon = miSedeForm.moneda || 'ARS';
                    const esEstandar = esDuracionPrecioAdminEstandar(row.duracion_minutos);
